import React from "react";
import { palette } from "../theme/palette";

/*
 * Sky pieces in 1080×1920 scene space: gradient sky, the recurring sun-on-a-wire motif,
 * stylised clouds and a distant palace skyline.
 */

export const SkyGradient: React.FC<{ top: string; mid: string; bottom: string; id: string }> = ({ top, mid, bottom, id }) => (
  <g>
    <defs>
      <linearGradient id={id} x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stopColor={top} />
        <stop offset="0.55" stopColor={mid} />
        <stop offset="1" stopColor={bottom} />
      </linearGradient>
    </defs>
    <rect width={1080} height={1920} fill={`url(#${id})`} />
  </g>
);

/** Point on the brass wire (quadratic arc across the top of the frame), t ∈ [0,1]. */
export const wirePoint = (t: number): [number, number] => {
  const p0 = [50, 600];
  const p1 = [540, 20];
  const p2 = [1030, 600];
  const u = 1 - t;
  return [u * u * p0[0] + 2 * u * t * p1[0] + t * t * p2[0], u * u * p0[1] + 2 * u * t * p1[1] + t * t * p2[1]];
};

/** The film's time-keeper: a gold sun (or ivory moon) hung from a thread on a brass wire. */
export const SunOnWire: React.FC<{ t: number; moon?: boolean; drop?: number; /** Night-sky colour that cuts the crescent. */ moonShadow?: string }> = ({
  t,
  moon = false,
  drop = 70,
  moonShadow = "#2B1B38",
}) => {
  const [wx, wy] = wirePoint(t);
  const cy = wy + drop;
  return (
    <g>
      <path d="M50 600 Q540 20 1030 600" fill="none" stroke={palette.brass} strokeWidth={2.2} opacity={0.8} />
      <circle cx={50} cy={600} r={6} fill="url(#foil)" />
      <circle cx={1030} cy={600} r={6} fill="url(#foil)" />
      <path d={`M${wx} ${wy} L${wx} ${cy - 62}`} stroke={palette.goldDeep} strokeWidth={1.2} />
      <circle cx={wx} cy={wy} r={4} fill="url(#foil)" />
      {moon ? (
        <g>
          <circle cx={wx} cy={cy} r={60} fill={palette.ivoryLight} />
          <circle cx={wx + 22} cy={cy - 10} r={52} fill={moonShadow} />
        </g>
      ) : (
        <g>
          <circle cx={wx} cy={cy} r={120} fill="#FFE4A6" opacity={0.25} />
          {new Array(16).fill(0).map((_, i) => (
            <path
              key={i}
              d="M-7 0 L0 -26 L7 0 Z"
              transform={`translate(${wx} ${cy}) rotate(${i * 22.5}) translate(0 -66)`}
              fill="url(#foil-v)"
            />
          ))}
          <circle cx={wx} cy={cy} r={60} fill="url(#foil)" />
          <circle cx={wx} cy={cy} r={48} fill="none" stroke={palette.goldPale} strokeWidth={1.4} opacity={0.8} />
        </g>
      )}
    </g>
  );
};

/** Flat-bottomed stylised cloud with scalloped crown. */
export const Cloud: React.FC<{ x: number; y: number; w: number; fill: string; line?: string }> = ({ x, y, w, fill, line }) => {
  const s = w / 300;
  return (
    <g transform={`translate(${x} ${y}) scale(${s})`}>
      <path
        d="M0 60 C0 36 22 24 44 30 C50 8 80 -4 104 8 C120 -12 160 -12 176 10 C196 -2 232 4 240 30 C268 24 300 38 300 60 Z"
        fill={fill}
      />
      {line ? <path d="M30 48 C80 40 120 44 160 40 C200 36 240 42 280 48" fill="none" stroke={line} strokeWidth={2} opacity={0.6} /> : null}
    </g>
  );
};

